    const units = [];
    for (let r = 0; r < 9; r++) units.push(Array.from({ length: 9 }, (x, k) => r * 9 + k));
    for (let c = 0; c < 9; c++) units.push(Array.from({ length: 9 }, (x, k) => k * 9 + c));
    for (let b = 0; b < 9; b++) { const br = ((b / 9) | 0) * 3, bc = (b % 9) * 3; const u = []; for (let dr = 0; dr < 3; dr++) for (let dc = 0; dc < 3; dc++) u.push((br + dr) * 9 + bc + dc); units.push(u); }
    let dupPairs = 0;
    for (const u of units) { const seen = {}; for (const i of u) { const d = v[i]; if (d === '') continue; if (seen[d] !== undefined) dupPairs++; else seen[d] = i; } }
    return { filled, empty: 81 - filled, dupPairs, complete: filled === 81 };
  }
  function noSuccessClaim(t) { return /solved|complete|congratul|winner|you win|correct solution/i.test(t) === false; }

  // A: Check on the loaded (incomplete) board
