  s = click('btn-check'); a = analyse(read());
  R.push({ name: 'B incomplete + conflict -> Check reports conflicts, not success', ok: s.state === 'conflicts' && a.dupPairs > 0 && noSuccessClaim(s.text), detail: a.dupPairs + ' dup pairs | ' + s.state + ' | ' + s.text });

  // C: complete but INVALID (duplicate in row 0) must not be reported as success
  click('btn-reset');
  for (let i = 0; i < 81; i++) if (SOL[i] !== '0') C[i].value = SOL[i];
  C[3].value = '8';
  s = click('btn-check'); a = analyse(read());
  R.push({ name: 'C complete but conflicting -> Check reports conflicts, not success', ok: s.state === 'conflicts' && a.complete && a.dupPairs > 0 && noSuccessClaim(s.text), detail: a.filled + ' filled, ' + a.dupPairs + ' dup | ' + s.state + ' | ' + s.text });

