  R.push({ name: 'F3 Solve preserves every given digit', ok: givensPreserved, detail: givensPreserved ? 'all 30 givens intact' : 'broken' });
  R.push({ name: 'F4 Solve marks status solved', ok: s.state === 'solved', detail: s.text });

